  "message": "I can help. To fix slow/dropping mobile data, I’ll do two things in parallel: (1) check your account/line for any issues (like data limit reached or a suspension) and (2) guide you through quick on‑device checks that commonly resolve speed problems. I’ll explain each step and why. First, I need to identify your account.",
  "why_these_steps": [
    "Account/line check: Confirms your line is active, roaming is set correctly, and whether you’ve hit your plan’s data limit (which can cut off data).",
    "Device checks: Ensures mobile data is ON, Airplane Mode is OFF, you’re set to 4G/5G, Data Saver/VPN aren’t slowing things down, and helps us measure your current speed."
  ],
  "request_account_verification": {
    "please_provide_one_of": [
      "Phone number on the affected line",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ],
    "also_needed": [
      "Confirm the exact phone number of the line having issues (if different from above)",
      "Your city and state (to see if this is location-specific)"
    ],
    "consent": "Do I have your permission to access your account to run diagnostics on your line and data usage?"
  },
  "device_checks_to_run_now": [
    {
      "action": "check_status_bar",
      "what_to_share_back": "Tell me if you see Airplane Mode, your signal strength (No Signal/1-4 bars), and the network type showing (5G/4G/etc.).",
      "reason": "Confirms you have cellular service and what network you’re on."
    },
    {
      "action": "check_network_status",
      "what_to_share_back": "Is Mobile Data shown as Enabled? What’s the signal strength and network type? Is Data Roaming OFF or ON?",
      "reason": "Verifies data is toggled ON and the phone sees the network properly."
    },
    {
      "action": "run_speed_test",
      "what_to_share_back": "Report the result category (unknown/very poor/poor/fair/good/excellent).",
      "reason": "We need excellent speed; this tells us the current performance level."
    },
    {
      "action": "check_network_mode_preference",
      "what_to_share_back": "What is the current preferred mode (e.g., 5G, 4G, 3G/2G)?",
      "reason": "If set to older modes (2G/3G), speeds will be very slow. We’ll switch to 4g_5g_preferred if needed."
    },
    {
      "action": "check_data_restriction_status",
      "what_to_share_back": "Is Data Saver ON or OFF? Are background data restrictions enabled?",
      "reason": "Data Saver can make apps seem slow or unresponsive."
    },
    {
      "action": "check_vpn_status",
      "what_to_share_back": "Is a VPN connected?",
      "reason": "VPNs can significantly reduce speed if the tunnel is slow."
    }
  ],
  "next_steps_after_you_reply": [
    "I’ll look up your line to confirm status and data usage for this cycle. If you’ve hit your plan limit, we can refuel up to 2 GB immediately or discuss plan change options.",
    "Based on your device readouts, I’ll guide you to: ensure Airplane Mode is OFF, turn Mobile Data ON, switch network mode to 4g_5g_preferred, turn OFF Data Saver, disconnect any VPN, and if needed reset APN and reboot.",
    "We’ll re-run a speed test to confirm you’re at Excellent."
  ]
}

