messages.content:
{
  "message": "I can help you fix MMS. First, I need to identify your account so I can also rule out line/roaming/data-limit issues. In parallel, we can run quick device checks that usually resolve MMS problems.",
  "why_these_steps": [
    "MMS needs working mobile data (even if SMS works). Common causes are mobile data off, Wi‑Fi Calling interference, incorrect APN/MMSC, app permissions, or roaming/data-limit issues."
  ],
  "request_for_identification": {
    "prompt": "Please verify your account with one of the following:",
    "acceptable_identifiers": [
      "Phone number on the affected line (preferred)",
      "Customer ID",
      "Full name + date of birth (YYYY-MM-DD)"
    ]
  },
  "questions": [
    "Are you currently connected to Wi‑Fi? If yes, can you turn Wi‑Fi OFF temporarily and try sending a picture again?",
    "Are you traveling outside your home network/country right now?",
    "With Wi‑Fi OFF, can other apps load over mobile data (e.g., a web page)?",
    "Do you see signal bars and 4G/5G in the status bar, and is Airplane Mode OFF?",
    "Has MMS worked on this device before today?"
  ],
  "guided_steps": [
    {
      "step": "Confirm basic connectivity",
      "do": "Turn Wi‑Fi OFF. Ensure Mobile Data is ON. Retry sending a small photo.",
      "reason": "MMS uses mobile data and often fails when it routes over Wi‑Fi or when data is off."
    },
    {
      "step": "Temporarily disable Wi‑Fi Calling",
      "do": "If Wi‑Fi Calling is ON, turn it OFF and retry MMS.",
      "reason": "Some configurations block MMS over Wi‑Fi Calling."
    },
    {
      "step": "Check network mode",
      "do": "Ensure your phone’s preferred network is set to 4G/5G (not 2G/3G only).",
      "reason": "2G/older modes can break MMS."
    },
    {
      "step": "Verify APN/MMSC",
      "do": "Open Access Point Names (APN) and confirm an MMSC URL is present. If unsure, reset APN to default, then reboot the phone and retry MMS.",
      "reason": "A missing/incorrect MMSC is a very common MMS failure cause."
    },
    {
      "step": "Check messaging app permissions",
      "do": "Ensure the default messaging app has Storage and SMS permissions allowed.",
      "reason": "Without these, the app can’t attach/send media."
    }
  ],
  "next_account_actions_after_verification": [
    "If you are roaming, I will enable roaming on your line (no cost) and guide you to enable Data Roaming on the phone.",
    "I will check if you’ve hit your data limit. If so, we can refuel up to 2 GB or change plan.",
    "I will confirm your line isn’t suspended and that there are no account blocks."
  ],
  "please_reply_with": [
    "Your account identifier (phone number, customer ID, or full name + DOB).",
    "Results of the quick checks above (especially: did MMS send with Wi‑Fi OFF and mobile data ON?).",
    "Whether you are traveling/roaming right now."
  ]
}

