  "message": "I’m on it. To fix “No Service,” I’ll first verify your line status on our side (in case it’s suspended or not registered) and, in parallel, walk you through the quickest device checks that usually bring service back.",
  "why": "No service is most commonly caused by airplane mode being on, a SIM/eSIM hiccup, a temporary network registration glitch, or a suspended line. Verifying your account rules out suspension, and the steps below refresh the phone’s connection.",
  "need_from_you": {
    "identification": "Please provide ONE of the following so I can look up your account/line:",
    "options": [
      "The phone number on the affected line (preferred)",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ],
    "extra_context": [
      "Are you traveling outside your usual area right now? If yes, where? (This helps me check roaming settings.)",
      "What phone do you have (iPhone or Android), and is it a physical SIM or eSIM?",
      "Did you recently change phones, swap SIMs, port a number, or change plans?"
    ]
  },
  "quick_checks_to_try_now": [
    {
      "step": "Check the status bar: Is Airplane Mode showing?",
      "how": "Open Quick Settings/Control Center and make sure Airplane Mode is OFF.",
      "reason": "Airplane Mode disables all cellular radios."
    },
    {
      "step": "Refresh the radio",
      "how": "Turn Airplane Mode ON for 10 seconds, then turn it OFF.",
      "reason": "Forces the device to re-register to the network."
    },
    {
      "step": "Reboot the phone",
      "how": "Power it off completely, wait 20 seconds, then power it back on.",
      "reason": "Clears temporary network registration glitches."
    },
    {
      "step": "SIM check",
      "how": "If you use a physical SIM, remove it and reinsert it carefully. If eSIM, skip this.",
      "reason": "A poorly seated SIM causes ‘No Service’."
    },
    {
      "step": "Network mode preference",
      "how": "Ensure the device is set to 4G/5G (not 2G/3G only).",
      "reason": "Older modes can fail to connect in some areas."
    }
  ],
  "next_steps_after_you_reply": [
    "I’ll pull up your account and confirm whether the line is active or suspended.",
    "If suspended due to billing, I’ll guide you to clear it and restore service.",
    "If you’re traveling, I’ll verify and enable data roaming on your line if needed (no cost).",
    "If the line is active, we’ll continue targeted device checks (SIM status, APN reset, etc.)."
  ]
}

