messages.content:
{
  "message": "You’ve got strong 5G data now, so MMS should work—let’s rule out the common MMS-specific blockers in order.",
  "thought_process": "With data confirmed excellent, the remaining likely causes are Wi‑Fi Calling interference, Data Saver/VPN restrictions, or an incorrect/blank MMSC in your APN. We’ll test each, one at a time.",
  "step_1_now": {
    "action": "Turn OFF Wi‑Fi Calling (temporarily) and retry the same MMS",
    "why": "On some networks, MMS can fail when Wi‑Fi Calling is enabled, especially while roaming.",
    "how_android_variants": [
      "Settings > Network & Internet (or Connections) > Mobile network (or SIMs) > Wi‑Fi Calling > turn OFF.",
      "Or: Phone app > Settings > Calls > Wi‑Fi Calling > turn OFF."
    ],
    "after": [
      "Keep Wi‑Fi itself OFF.",
      "Reopen Messages and resend the same small photo to your own number.",
      "Watch for ‘Sent/Delivered’ or any error."
    ]
  },
  "what_to_reply_after_step_1": [
    "Was Wi‑Fi Calling ON, and is it now OFF?",
    "Did the MMS send successfully after turning Wi‑Fi Calling OFF? If not, what error do you see?"
  ],
  "next_steps_preview_if_it_still_fails": [
    {
      "step_2": {
        "action": "Make sure Data Saver is OFF",
        "how_android": "Settings > Network & Internet > Data Saver > turn OFF."
      }
    },
    {
      "step_3": {
        "action": "Ensure no VPN is active",
        "how_android": "Settings > Network & Internet > VPN > disconnect any active VPN."
      }
    },
    {
      "step_4": {
        "action": "Check APN for MMSC; if unsure, reset APN to default and reboot",
        "how_android": [
          "Settings > Network & Internet (or Connections) > Mobile network (or SIMs) > Access Point Names.",
          "Open the active APN and look for ‘MMSC’ (MMS server) — if missing/blank or you’re unsure, use the menu to ‘Reset to default’.",
          "After resetting, restart the phone: hold Power > Restart.",
          "Once restarted, keep Wi‑Fi OFF and try the MMS again."
        ]
      }
    },
    {
      "step_5": {
        "action": "Verify Messages app permissions",
        "how_android": "Settings > Apps > Messages > Permissions > ensure Storage (or Photos/Media) and SMS are allowed; then retry MMS."
      }
    }
  ]
}

