messages.content:
{
  "thought_process": "Since you have strong 5G signal, data enabled, roaming ON, and MMS still fails, the most likely cause is APN/MMSC configuration on the phone. We’ll first verify whether the MMSC is populated, then (regardless of what we find) reset APN to default and reboot to apply clean carrier settings.",
  "step_now": {
    "title": "Check APN/MMSC on your phone",
    "why": "MMS requires a valid MMSC URL in your APN. If it’s missing/incorrect, MMS won’t send.",
    "instructions": {
      "iPhone": [
        "Open Settings > Cellular (or Mobile Data) > Cellular Data Options > Cellular Data Network.",
        "Scroll to the MMS section and look for MMSC.",
        "Note whether MMSC shows a URL or is blank."
      ],
      "Android": [
        "Open Settings > Network & Internet (or Connections) > Mobile network (or SIMs) > Access Point Names.",
        "Tap your carrier APN entry.",
        "Scroll to MMSC and note whether it shows a URL (http/https) or is blank."
      ]
    },
    "what_to_reply": "Tell me if the MMSC field is populated with a URL or blank."
  },
  "next_step_preview": {
    "title": "Reset APN to default, then reboot",
    "android": [
      "In the APN screen, tap the three‑dot menu (or More) > Reset to default (or Reset APNs).",
      "Confirm. Ensure your carrier APN reappears and is selected.",
      "Then restart the phone (power off, wait 15 seconds, power on)."
    ],
    "iphone": [
      "Go to Settings > General > Transfer or Reset iPhone > Reset > Reset Network Settings.",
      "Note: This also clears saved Wi‑Fi networks/Bluetooth pairings—you can reconnect later.",
      "The phone will reboot automatically. If not, power it off and on."
    ],
    "after_reboot": [
      "Wait 60–90 seconds for the network to attach.",
      "Keep Wi‑Fi OFF and Wi‑Fi Calling OFF.",
      "Try sending a small photo MMS to a contact.",
      "If MMS still fails, we’ll check messaging app permissions next."
    ]
  }
}

