messages.content:
{
  "thought_process": "Since signal and data are good and MMSC is now set, the next most likely blocker is the messaging app’s permissions and background data access. Let’s fix that first; if MMS still fails, we’ll do a quick Airplane Mode cycle and then check Data Saver/VPN.",
  "step_now": {
    "title": "Check and grant messaging app permissions (do this first)",
    "why": "MMS needs permission to access media (photos/videos) and to send messages. It also needs background data allowed.",
    "instructions": {
      "Android": [
        "Open Settings > Apps > (Your messaging app, e.g., Messages).",
        "Tap Permissions:",
        "- Allow SMS (or Messages).",
        "- Allow Photos and videos (or Storage/Files and media).",
        "Back one level > Mobile data & Wi‑Fi (or Data usage):",
        "- Turn ON Background data.",
        "- Turn ON Unrestricted data usage (or Allow data usage while Data Saver is on), if available."
      ],
      "iPhone": [
        "Open Settings > Messages:",
        "- Ensure MMS Messaging is ON.",
        "Open Settings > Privacy & Security > Photos > Messages:",
        "- Set to All Photos (or at least allow access).",
        "Open Settings > Cellular (or Mobile Data):",
        "- Ensure Cellular Data is ON.",
        "- Scroll down and confirm Messages is allowed to use cellular data."
      ]
    },
    "what_to_do_after": [
      "Stay on mobile data (Wi‑Fi OFF, Wi‑Fi Calling OFF).",
      "Open your messaging app and try sending a small photo MMS again."
    ]
  },
  "what_to_reply": "Please reply with: 1) your phone type (Android or iPhone), 2) which permissions/toggles you changed (if any), and 3) whether the MMS now sends successfully.",
  "next_step_preview": {
    "if_still_fails": [
      "We’ll do a quick Airplane Mode ON (10s) then OFF reattach.",
      "Then we’ll check Data Saver/background restriction globally and any VPN."
    ]
  }
}

